def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(w * 3)] for _ in range(h * 3)]
    motifs = {
        3: ((0, 2), (1, 2), (2, 2)),
        4: ((0, 2), (1, 0), (1, 1), (2, 0), (2, 1)),
        6: ((0, 0), (0, 1), (1, 0), (1, 2), (2, 1), (2, 2)),
        7: ((0, 0), (0, 2), (2, 0), (2, 2)),
    }
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                for dr, dc in motifs[value]:
                    out[r * 3 + dr][c * 3 + dc] = value
    return out

